import {getSession} from "@/lib/auth"; import {query} from "@/lib/db"; import {Brand} from "@/components/Brand";
export default async function Student(){const s=await getSession();if(!s)return <main className="login-page"><div className="login-card"><Brand/><h1>Please sign in</h1><p className="muted">Your student dashboard is protected.</p><a className="btn btn-primary" href="/login">Login</a></div></main>;const courses=await query(`SELECT c.id,c.title,c.slug,c.price,COALESCE(ROUND(AVG(lp.watch_percentage)),0)::int progress FROM enrollments e JOIN courses c ON c.id=e.course_id LEFT JOIN subjects su ON su.course_id=c.id LEFT JOIN chapters ch ON ch.subject_id=su.id LEFT JOIN lessons l ON l.chapter_id=ch.id LEFT JOIN lesson_progress lp ON lp.lesson_id=l.id AND lp.student_id=e.student_id WHERE e.student_id=$1 GROUP BY c.id ORDER BY e.enrolled_at DESC`,[s.id]);return <div className="dashboard"><aside className="sidebar"><Brand/><nav><a className="active" href="/student">⌂ Dashboard</a><a href="/courses">▦ Courses</a><a href="#">▶ Learn</a><a href="#">▣ Tests</a><a href="#">◉ Messages</a><a href="#">● Notifications</a><a href="#">⚙ Settings</a></nav></aside><main className="main"><div className="section-head"><div><span className="eyebrow">STUDENT DASHBOARD</span><h2>Good Morning, {s.name.split(" ")[0]} 👋</h2><p className="muted">Keep going — your goals are within reach.</p></div><a className="btn btn-secondary" href="/courses">+ Explore Courses</a></div><div className="stats"><div className="stat"><div className="icon">📚</div><strong>{courses.rowCount}</strong><span className="muted">My courses</span></div><div className="stat"><div className="icon">▶</div><strong>{courses.rows.filter((x:any)=>x.progress>0).length}</strong><span className="muted">In progress</span></div><div className="stat"><div className="icon">✓</div><strong>{courses.rows.filter((x:any)=>x.progress>=90).length}</strong><span className="muted">Completed</span></div><div className="stat"><div className="icon">⚡</div><strong>Active</strong><span className="muted">Learning status</span></div></div><section className="section" style={{paddingBottom:0}}><div className="section-head"><h2 style={{fontSize:24}}>My Courses</h2></div><div className="course-grid">{courses.rows.map((c:any)=><article className="course-card" key={c.id}><div className="course-cover"><span className="tag">ENROLLED</span><b>KP PHYSICS</b></div><div className="course-body"><h3>{c.title}</h3><div className="course-meta"><span>Learning progress</span><strong>{c.progress}%</strong></div><div className="progress"><i style={{width:`${c.progress}%`}}/></div><a className="btn btn-primary" style={{width:"100%",marginTop:14}} href={`/courses/${c.slug}`}>Continue Learning →</a></div></article>)}</div></section></main></div>}
